metric.weekly.expression:
(
  $decimalText := function($v) {(
    $t := $type($v);
    $assert($t = "string" or $t = "number", "usage value must be a decimal scalar");
    $s := $trim($string($v));
    $assert($length($s) <= 128 and $contains($s, /^[+-]?[0-9]+(\.[0-9]+)?([eE][+-]?[0-9]{1,3})?$/), "usage value must be bounded decimal text");
    $parts := $split($s, /[eE]/);
    $mantissa := $parts[0];
    $exponent := $count($parts) = 2 ? $number($parts[1]) : 0;
    $assert($abs($exponent) <= 128, "usage exponent unsupported");
    $negative := $substring($mantissa, 0, 1) = "-";
    $unsigned := $contains($substring($mantissa, 0, 1), /[+-]/) ? $substring($mantissa, 1) : $mantissa;
    $pieces := $split($unsigned, ".");
    $digits := $join($pieces, "");
    $point := $length($pieces[0]) + $exponent;
    $expanded := $point <= 0 ? "0." & $pad("", -$point, "0") & $digits :
      $point >= $length($digits) ? $digits & $pad("", $point - $length($digits), "0") :
      $substring($digits, 0, $point) & "." & $substring($digits, $point);
    $expandedParts := $split($expanded, ".");
    $whole := $replace($expandedParts[0], /^0+/, "");
    $fraction := $exists($expandedParts[1]) ? $replace($expandedParts[1], /0+$/, "") : "";
    $canonical := ($length($whole) > 0 ? $whole : "0") & ($length($fraction) > 0 ? "." & $fraction : "");
    ($negative and $canonical != "0" ? "-" : "") & $canonical
  )};
  $percentText := function($v) {
    $type($v) = "object" ? (
      $assert($exists($v.val) and $v.val != null, "percentage wrapper requires val");
      $decimalText($v.val)
    ) : $decimalText($v)
  };
  $centText := function($v) {(
    $raw := $type($v) = "object" ? (
      $count($keys($v)) = 0 ? "0" : (
        $assert($exists($v.val) and $v.val != null, "cent wrapper requires val");
        $v.val
      )
    ) : $v;
    $s := $decimalText($raw);
    $assert($contains($s, /^-?(0|[1-9][0-9]*)(\.0+)?$/), "credits must be integer cents");
    $replace($s, /\.0+$/, "")
  )};
  $validReset := function($s) {
    $type($s) != "string" ? false :
    $not($contains($s, /^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](\.[0-9]+)?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])$/)) ? false : (
      $year := $number($substring($s, 0, 4));
      $month := $number($substring($s, 5, 2));
      $day := $number($substring($s, 8, 2));
      $leap := $year % 400 = 0 or ($year % 4 = 0 and $year % 100 != 0);
      $days := [31, $leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
      $year > 0 and $day <= $days[$month - 1]
    )
  };
  $c := billing.config;
  $hasPercent := $exists($c.creditUsagePercent) and $c.creditUsagePercent != null;
  $legacy := ($not($exists($c.currentPeriod)) or $c.currentPeriod = null) and
    $not($hasPercent) and $not($c.isUnifiedBillingUser = true) and
    $exists($c.monthlyLimit) and $c.monthlyLimit != null;
  $remaining := $hasPercent ? (
    $percent := $percentText($c.creditUsagePercent);
    $assert($qxDecimalCompare($percent, "0") >= 0, "usage percentage must be non-negative");
    $qxDecimalSubtract("100", $percent)
  ) :
    ($legacy and $exists($c.used) and $c.used != null) ? (
      $limit := $centText($c.monthlyLimit);
      $used := $centText($c.used);
      $assert($qxDecimalCompare($used, "0") >= 0, "credits used must be non-negative");
      $qxDecimalCompare($limit, "0") > 0 ?
        $qxDecimalMultiply($qxDecimalDivide($qxDecimalSubtract($limit, $used), $limit), "100")
    );
  $end := $hasPercent ? $c.currentPeriod.end : ($legacy ? $c.billingPeriodEnd);
  $exists($remaining) ? {
    "availability": "available",
    "value": {"kind": "ratio", "remainingPercent": $remaining},
    "reset": $validReset($end) ? {
      "kind": "scheduled", "at": $fromMillis($toMillis($end)), "confidence": "exact",
      "cycleKey": null, "lastConfirmedResetAt": null
    } : {"kind": "unknown"},
    "entitlementSubjectKeys": []
  } : {"availability": "notProvided", "value": null, "reset": {"kind": "unknown"}, "entitlementSubjectKeys": []}
)

